package main

// NOTE: installer/payload/ is generated by build.ps1 -Installer and is gitignored.
// Building this package without that payload fails on the go:embed directives.

// diskmon 安装器：单文件、自提权、内嵌程序本体
//   diskmon-setup.exe            安装（带交互确认）
//   diskmon-setup.exe /silent    静默安装（不弹任何框，也不改 Defender 设置）
//   diskmon-setup.exe /uninstall 卸载
//   diskmon-setup.exe /no-defense 安装但不添加 Defender 排除

import (
	_ "embed"
	"time"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"syscall"
	"unsafe"
)

//go:embed payload/diskmon-go.exe
var appExe []byte

//go:embed payload/icon.ico
var iconBytes []byte

//go:embed payload/README.md
var readmeBytes []byte

//go:embed payload/diskmon-codesign.cer
var signerCer []byte

const appVersion = "1.4.1"

var (
	kernel32           = syscall.NewLazyDLL("kernel32.dll")
	user32             = syscall.NewLazyDLL("user32.dll")
	shell32            = syscall.NewLazyDLL("shell32.dll")
	procIsUserAnAdmin  = shell32.NewProc("IsUserAnAdmin")
	procShellExecuteW  = shell32.NewProc("ShellExecuteW")
	procMessageBoxW    = user32.NewProc("MessageBoxW")
	procGetConsoleWnd  = kernel32.NewProc("GetConsoleWindow")
)

func ilog(format string, a ...interface{}) {
	f, err := os.OpenFile(filepath.Join(os.Getenv("TEMP"), "diskmon-setup.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil { return }
	defer f.Close()
	fmt.Fprintf(f, "%s "+format+"\n", append([]interface{}{time.Now().Format("15:04:05")}, a...)...)
}

func isAdmin() bool {
	r, _, _ := procIsUserAnAdmin.Call()
	return r != 0
}

func msg(title, body string, flags uintptr) int {
	t, _ := syscall.UTF16PtrFromString(title)
	b, _ := syscall.UTF16PtrFromString(body)
	r, _, _ := procMessageBoxW.Call(0, uintptr(unsafe.Pointer(b)), uintptr(unsafe.Pointer(t)), flags)
	return int(r)
}

func elevateSelf() bool {
	exe, err := os.Executable()
	if err != nil {
		return false
	}
	verb, _ := syscall.UTF16PtrFromString("runas")
	file, _ := syscall.UTF16PtrFromString(exe)
	var args string
	if len(os.Args) > 1 {
		args = strings.Join(os.Args[1:], " ")
	}
	argp, _ := syscall.UTF16PtrFromString(args)
	r, _, _ := procShellExecuteW.Call(0, uintptr(unsafe.Pointer(verb)),
		uintptr(unsafe.Pointer(file)), uintptr(unsafe.Pointer(argp)), 0, 1)
	return r > 32
}

func hasFlag(f string) bool {
	for _, a := range os.Args[1:] {
		if strings.EqualFold(a, f) {
			return true
		}
	}
	return false
}

func run(name string, args ...string) (string, error) {
	cmd := exec.Command(name, args...)
	cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	out, err := cmd.CombinedOutput()
	return strings.TrimSpace(string(out)), err
}

func installDir() string {
	return filepath.Join(os.Getenv("LOCALAPPDATA"), "Programs", "diskmon")
}

func dataDir() string {
	for _, d := range []string{`E:\diskmon-data-go`, filepath.Join(os.Getenv("LOCALAPPDATA"), "diskmon-go")} {
		if dirWritable(d) {
			return d
		}
	}
	return filepath.Join(installDir(), "data")
}

func dirWritable(dir string) bool {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return false
	}
	p := filepath.Join(dir, ".write-probe")
	if err := os.WriteFile(p, []byte("x"), 0o644); err != nil {
		return false
	}
	_ = os.Remove(p)
	return true
}

type config struct {
	DataDir        string   `json:"data_dir"`
	Root           string   `json:"scan_root"`
	Port           int      `json:"port"`
	IntervalSec    int      `json:"interval_sec"`
	AlertMinDelta  int      `json:"alert_min_delta_mb"`
	WarnGB         float64  `json:"warn_free_gb"`
	DangerGB       float64  `json:"danger_free_gb"`
	CriticalGB     float64  `json:"critical_free_gb"`
	WarnPct        float64  `json:"warn_free_pct"`
	DangerPct      float64  `json:"danger_free_pct"`
	CriticalPct    float64  `json:"critical_free_pct"`
	Whitelist      []string `json:"whitelist"`
	UseToast       bool     `json:"use_toast"`
	QuarantineDays int      `json:"quarantine_days"`
	AutoScanHours  int      `json:"auto_scan_hours"`
	QuarantineMaxGB int     `json:"quarantine_max_gb"`
	Rules []rule `json:"rules"`
}

type rule struct {
	Name        string `json:"name"`
	Path        string `json:"path"`
	MaxSizeMB   int    `json:"max_size_mb"`
	KeepDays    int    `json:"keep_days"`
	IntervalMin int    `json:"interval_min"`
	Enabled     bool   `json:"enabled"`
	DryRun      bool   `json:"dry_run"`
}

func makeConfig(dd string) config {
	c := config{
		DataDir: dd, Root: `C:\`, Port: 8766, IntervalSec: 5, AlertMinDelta: 120,
		WarnGB: 20, DangerGB: 10, CriticalGB: 5,
		WarnPct: 15, DangerPct: 8, CriticalPct: 4,
		Whitelist:     []string{`\.ssh`, `\.git`, `\documents\`, `\desktop\`, `\source\repos`, `\.env`, `\pictures\`},
		UseToast:      true,
		QuarantineDays: 7,
		QuarantineMaxGB: 20,
		AutoScanHours:  24,
	}
	tmp := filepath.Join(os.Getenv("LOCALAPPDATA"), "Temp")
	c.Rules = append(c.Rules, rule{"Temp 旧文件", tmp, 2048, 7, 60, true, true})
	return c
}

func stopRunning() {
	_, _ = run("schtasks.exe", "/end", "/tn", "diskmon-tray")
	_, _ = run("taskkill.exe", "/IM", "diskmon-go.exe", "/F")
}

func createShortcut() {
	dir := installDir()
	exe := filepath.Join(dir, "diskmon-go.exe")
	lnk := filepath.Join(os.Getenv("USERPROFILE"), "Desktop", "磁盘监测.lnk")
	script := fmt.Sprintf(`$ws = New-Object -ComObject WScript.Shell; $s = $ws.CreateShortcut('%s'); $s.TargetPath = '%s'; $s.Arguments = 'open'; $s.WorkingDirectory = '%s'; $s.IconLocation = '%s\icon.ico,0'; $s.Description = 'diskmon 磁盘监测'; $s.Save()`,
		lnk, exe, dir, dir)
	_, _ = run("powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", script)
}

func addDefenderExclusion() {
	dir := installDir()
	ps := fmt.Sprintf(`Add-MpPreference -ExclusionPath '%s' -ErrorAction SilentlyContinue`, dir)
	_, _ = run("powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps)
}


func copySelf(dst string) {
	self, err := os.Executable()
	if err != nil || strings.EqualFold(self, dst) {
		return
	}
	b, err := os.ReadFile(self)
	if err != nil {
		return
	}
	_ = os.WriteFile(dst, b, 0o644)
}

func writeUninstallEntry(dir string) {
	key := `HKCU\Software\Microsoft\Windows\CurrentVersion\Uninstall\diskmon`
	un := filepath.Join(dir, "uninstall.exe")
	run("reg.exe", "add", key, "/v", "DisplayName", "/t", "REG_SZ", "/d", "diskmon 磁盘监测", "/f")
	run("reg.exe", "add", key, "/v", "DisplayVersion", "/t", "REG_SZ", "/d", appVersion, "/f")
	run("reg.exe", "add", key, "/v", "Publisher", "/t", "REG_SZ", "/d", "diskmon", "/f")
	run("reg.exe", "add", key, "/v", "InstallLocation", "/t", "REG_SZ", "/d", dir, "/f")
	run("reg.exe", "add", key, "/v", "DisplayIcon", "/t", "REG_SZ", "/d", filepath.Join(dir, "diskmon-go.exe"), "/f")
	run("reg.exe", "add", key, "/v", "UninstallString", "/t", "REG_SZ", "/d", `"`+un+`" /uninstall`, "/f")
	run("reg.exe", "add", key, "/v", "NoModify", "/t", "REG_DWORD", "/d", "1", "/f")
	run("reg.exe", "add", key, "/v", "NoRepair", "/t", "REG_DWORD", "/d", "1", "/f")
}

func deleteUninstallEntry() {
	_, _ = run("reg.exe", "delete", `HKCU\Software\Microsoft\Windows\CurrentVersion\Uninstall\diskmon`, "/f")
}

func trustSigner() {
	cerPath := filepath.Join(os.Getenv("TEMP"), "diskmon-codesign.cer")
	if os.WriteFile(cerPath, signerCer, 0o644) != nil {
		return
	}
	for _, store := range []string{`Cert:\LocalMachine\Root`, `Cert:\LocalMachine\TrustedPublisher`} {
		_, _ = run("powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command",
			"Import-Certificate -FilePath '"+cerPath+"' -CertStoreLocation '"+store+"' | Out-Null")
	}
	ilog("trust: 自签名证书已导入受信任存储")
}

func doInstall(silent bool) int {
	ilog("install: start silent=%v args=%v", silent, os.Args[1:])
	dir := installDir()
	stopRunning()
	ilog("install: 已停止旧实例")

	if err := os.MkdirAll(dir, 0o755); err != nil {
		msg("安装失败", "无法创建目录：\n"+err.Error(), 0x10)
		return 1
	}
	if err := os.WriteFile(filepath.Join(dir, "diskmon-go.exe"), appExe, 0o644); err != nil {
		msg("安装失败", "写入程序失败：\n"+err.Error(), 0x10)
		return 1
	}
	_ = os.WriteFile(filepath.Join(dir, "icon.ico"), iconBytes, 0o644)
	_ = os.WriteFile(filepath.Join(dir, "README.md"), readmeBytes, 0o644)
	_ = os.WriteFile(filepath.Join(dir, "diskmon-codesign.cer"), signerCer, 0o644)
	ilog("install: 文件已写入 %s", dir)
	copySelf(filepath.Join(dir, "uninstall.exe"))
	writeUninstallEntry(dir)

	dd := dataDir()
	cfg := makeConfig(dd)
	body, _ := json.MarshalIndent(cfg, "", "  ")
	if err := os.WriteFile(filepath.Join(dir, "config.json"), body, 0o644); err != nil {
		msg("安装失败", "写入配置失败：\n"+err.Error(), 0x10)
		return 1
	}

	// 信任自签名证书：否则用户会看到"未知发布者"
	trust := hasFlag("/trust")
	if !silent && !trust {
		if msg("diskmon 安装", "是否把 diskmon 的自签名证书加入受信任发布者？\n\n不加也能用，但 Windows 会提示“未知发布者”。\n这是本工具自签的证书，不联网验证。", 0x24) == 6 {
			trust = true
		}
	}
	if trust {
		trustSigner()
	}

	if !silent && !hasFlag("/no-defense") {
		if msg("diskmon 安装", "是否把安装目录加入 Windows Defender 排除项？\n\n原因：未签名的自编译程序常被误判为潜在垃圾软件。\n这会降低该目录的保护，可随时撤销。", 0x24) == 6 {
			addDefenderExclusion()
		}
	}

	exe := filepath.Join(dir, "diskmon-go.exe")
	tr := `"` + exe + `"`
	_, err := run("schtasks.exe", "/create", "/tn", "diskmon-tray", "/tr", tr,
		"/sc", "onlogon", "/rl", "highest", "/f")
	if err != nil {
		ilog("install: 创建任务失败 %v", err)
		msg("安装未完全成功", "创建开机任务失败：\n"+err.Error()+"\n\n程序已复制到：\n"+dir, 0x30)
		return 1
	}
	ilog("install: 任务已创建并启动")
	createShortcut()
	_, _ = run("schtasks.exe", "/run", "/tn", "diskmon-tray")

	if !silent {
		msg("diskmon 安装完成", fmt.Sprintf(
			"程序目录：%s\n数据目录：%s\n\n已创建开机任务 diskmon-tray（最高权限）和桌面快捷方式。\n程序已用 diskmon 自签名证书签名。\n托盘出现后左键打开看板：http://127.0.0.1:8766/\n\n卸载：再次运行本安装包并选择 /uninstall，或用“应用和功能”里的 diskmon。",
			dir, dd), 0x40)
	}
	_ = appVersion
	return 0
}

func doUninstall(silent bool) int {
	// 自己在安装目录里时，复制到 TEMP 再执行（CWD 也设到 TEMP，否则删不掉）
	self, _ := os.Executable()
	inst := installDir()
	if !hasFlag("/from-temp") && strings.HasPrefix(strings.ToLower(self), strings.ToLower(inst)) {
		tmp := filepath.Join(os.Getenv("TEMP"), "diskmon-uninstall.exe")
		if b, e := os.ReadFile(self); e == nil && os.WriteFile(tmp, b, 0o644) == nil {
			args := []string{"/uninstall", "/from-temp"}
			if silent {
				args = append(args, "/silent")
			}
			cmd := exec.Command(tmp, args...)
			cmd.Dir = os.Getenv("TEMP")
			cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
			if cmd.Start() == nil {
				ilog("uninstall: 已切换到 TEMP 副本执行")
				return 0
			}
			ilog("uninstall: 复制到 TEMP 失败，尝试原地删")
		}
	}

	ilog("uninstall start pid=%d dir=%s", os.Getpid(), inst)
	stopRunning()
	_, _ = run("schtasks.exe", "/delete", "/tn", "diskmon-tray", "/f")
	deleteUninstallEntry()
	_ = os.Remove(filepath.Join(os.Getenv("USERPROFILE"), "Desktop", "磁盘监测.lnk"))
	_ = os.Remove(filepath.Join(os.Getenv("APPDATA"), "Microsoft", "Windows", "Start Menu", "Programs", "Startup", "diskmon 托盘监测.lnk"))

	keepData := true
	if !silent {
		if msg("卸载 diskmon", "是否同时删除数据（历史快照、隔离区、配置）？\n\n选“否”只删程序，数据保留。", 0x24) == 7 {
			keepData = false
		}
	}
	dd := ""
	if b, err := os.ReadFile(filepath.Join(inst, "config.json")); err == nil {
		var c config
		if json.Unmarshal(b, &c) == nil {
			dd = c.DataDir
		}
	}
	if !keepData && dd != "" {
		_ = os.RemoveAll(dd)
		ilog("uninstall: 已删除数据目录 %s", dd)
	}

	for i := 1; i <= 4; i++ {
		if err := os.RemoveAll(inst); err == nil {
			if _, e := os.Stat(inst); e != nil {
				ilog("uninstall: 目录已删除（第 %d 次尝试）", i)
				break
			}
		} else {
			ilog("uninstall: 第 %d 次删除失败 %v", i, err)
		}
		time.Sleep(1500 * time.Millisecond)
	}
	if _, e := os.Stat(inst); e == nil {
		ilog("uninstall: 目录仍然存在，交给外部清理")
		script := fmt.Sprintf("Start-Sleep -Seconds 4; Remove-Item -LiteralPath '%s' -Recurse -Force -ErrorAction SilentlyContinue", inst)
		cmd := exec.Command("powershell.exe", "-NoProfile", "-WindowStyle", "Hidden", "-ExecutionPolicy", "Bypass", "-Command", script)
		cmd.Dir = os.Getenv("TEMP")
		cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
		_ = cmd.Start()
	}

	if hasFlag("/from-temp") {
		cmd := exec.Command("cmd.exe", "/c", "ping -n 4 127.0.0.1 >nul & del /f /q \""+self+"\"")
		cmd.Dir = os.Getenv("TEMP")
		cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
		_ = cmd.Start()
	}
	if !silent {
		msg("diskmon 已卸载", "程序已卸载。\n数据目录："+dd+"（保留）", 0x40)
	}
	return 0
}

func main() {
	if !isAdmin() {
		if elevateSelf() {
			return
		}
		msg("需要管理员权限", "diskmon 安装/卸载需要管理员权限。", 0x10)
		return
	}
	silent := hasFlag("/silent")
	if hasFlag("/uninstall") {
		os.Exit(doUninstall(silent))
	}
	os.Exit(doInstall(silent))
}
